from rules import dependencies, in_root_range, is_acyclic


def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def search(bounds, selected):
        nonlocal best_vector, best_versions

        unresolved = sorted(set(bounds) - set(selected))
        if not unresolved:
            if not is_acyclic(selected, features):
                return
            vector = tuple(
                selected[name]['version'] if name in selected else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: row['version'] for name, row in selected.items()
                }
            return

        name = unresolved[0]
        for row in packages.get(name, []):
            version = row['version']
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if not in_root_range(version, bounds[name]):
                continue

            next_selected = dict(selected)
            next_selected[name] = row
            next_bounds = dict(bounds)
            valid = True

            for dependency in dependencies(row, features):
                dep_name = dependency['name']
                dep_min = dependency['min']
                dep_max = dependency['max']
                old_min, old_max = next_bounds.get(
                    dep_name, (dep_min, dep_max)
                )
                new_min = max(old_min, dep_min)
                new_max = min(old_max, dep_max)
                if new_min > new_max:
                    valid = False
                    break
                next_bounds[dep_name] = (new_min, new_max)

            if not valid:
                continue
            if any(
                not in_root_range(next_selected[dep_name]['version'], interval)
                for dep_name, interval in next_bounds.items()
                if dep_name in next_selected
            ):
                continue

            search(next_bounds, next_selected)

    search({name: tuple(interval) for name, interval in roots.items()}, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def in_root_range(version, bounds):
    lower, upper = bounds
    return lower <= version <= upper


def dependencies(row, features=()):
    enabled = set(features)
    return [
        dependency
        for dependency in row['deps']
        if not dependency.get('feature') or dependency['feature'] in enabled
    ]


def is_acyclic(selected, features=()):
    graph = {name: [] for name in selected}
    for name, row in selected.items():
        for dependency in dependencies(row, features):
            target = dependency['name']
            if target not in selected:
                return False
            graph[name].append(target)

    state = {}

    def visit(name):
        if state.get(name) == 1:
            return False
        if state.get(name) == 2:
            return True
        state[name] = 1
        for target in graph[name]:
            if not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)
